import android.content.Context;import java.net.InetAddress;import java.util.*;import app.template.extension.extension.*;import com.brother.sdk.network.BrDatagramSocket;import com.brother.sdk.common.socket.devicemanagement.snmp.*;import com.brother.sdk.common.socket.devicemanagement.snmp.westhawk.*;
public class ReplayTransportTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}static SnmpResult ok(String oid,AsnObject value){SnmpResult r=new SnmpResult();r.results=new Varbind[]{new Varbind(oid,value)};return r;}
 public static void main(String[] args)throws Exception{Context context=new Context();AutoCache.init(context);String ip="192.0.2.33",mac="1.3.6.1.2.1.2.2.1.6.1",oid="1.2.3";BrDatagramSocket socket=new BrDatagramSocket(InetAddress.getByName(ip));AutoCache.record(socket,new SnmpRequest(mac,-96),ok(mac,new AsnOctets(new byte[]{2,1,2,3,4,5})));SnmpRequest r=new SnmpRequest(oid,-96);check(AutoCache.lookup(socket,r,200,10)==null,"initial miss");AutoCache.record(socket,r,ok(oid,new AsnInteger(7)));check(AutoCache.lookup(socket,r,200,10)!=null,"cache hit captured");CommunicationTiming.finishAll();List<ReplayEngine.Spec> seq=CommunicationTiming.replaySequence(ip);check(seq.size()==2&&seq.get(0).timeout==200&&seq.get(0).retries==10&&seq.get(0).port==161,"capture exact request order and transport settings");Map<String,String> old=AutoCache.replaySnapshot(ip,seq);Map<String,?> preferencesBefore=context.getSharedPreferences("morphe_printer_cache_v1",0).getAll();Diagnostics.clear();Diagnostics.start();SnmpClient.sent.clear();ReplayEngine.Result result=ReplayEngine.run(seq,old,"02:01:02:03:04:05",new ReplayTransport(ip,seq.get(0)));Diagnostics.stop();check(SnmpClient.sent.equals(Arrays.asList(mac,oid,oid)),"probe followed by sequential live requests");check(result.completed==2&&result.changes.size()==1,"fresh data compared");check(Diagnostics.count()==0,"replay must not appear in normal diagnostics");check(AutoCache.replaySnapshot(ip,seq).equals(old),"replay must not overwrite cache");check(context.getSharedPreferences("morphe_printer_cache_v1",0).getAll().equals(preferencesBefore),"replay must not mutate saved preferences");check(CommunicationTiming.replaySequence(ip).size()==2,"replay must not replace recorded sequence");SnmpClient.sent.clear();try{ReplayEngine.run(seq,old,"02:09:09:09:09:09",new ReplayTransport(ip,seq.get(0)));throw new AssertionError("wrong printer");}catch(ReplayEngine.ProbeException expected){}check(SnmpClient.sent.equals(Arrays.asList(mac)),"wrong printer aborts before replay");check(context.getSharedPreferences("morphe_printer_cache_v1",0).getAll().equals(preferencesBefore),"wrong printer leaves preferences unchanged");SnmpClient.sent.clear();SnmpClient.timeouts.clear();ReplayEngine.Spec unlimited=new ReplayEngine.Spec(oid,"public",0,1,161,0,1);ReplayEngine.run(Arrays.asList(unlimited),old,"02:01:02:03:04:05",new ReplayTransport(ip,unlimited));check(SnmpClient.timeouts.equals(Arrays.asList(2000,3000)),"unlimited original timeout receives finite replay fallback");SnmpClient.sent.clear();SnmpClient.offline=true;try{ReplayEngine.run(seq,old,"02:01:02:03:04:05",new ReplayTransport(ip,seq.get(0)));throw new AssertionError("offline probe");}catch(ReplayEngine.ProbeException expected){}check(SnmpClient.sent.equals(Arrays.asList(mac)),"offline aborts before replay");check(AutoCache.replaySnapshot(ip,seq).equals(old),"offline probe changes nothing");check(context.getSharedPreferences("morphe_printer_cache_v1",0).getAll().equals(preferencesBefore),"failed probe must not mutate saved preferences");System.out.println("Replay transport and cache isolation checks passed");}
}

